from __future__ import annotations

import base64
import zlib
from pathlib import Path

FILES = {
    'rust/silent-disco-core/src/storage/database.rs': '',
    'rust/silent-disco-core/src/storage/worker.rs': '',
}

for path, encoded in FILES.items():
    Path(path).write_bytes(zlib.decompress(base64.b64decode(encoded)))

Path('.github/scripts/apply_block8_storage.py').unlink()
Path('.github/workflows/block8-storage-bootstrap.yml').unlink()
